from typing import List

def eventualSafeNodes(V: int, adj: List[List[int]]) -> List[int]:
    color = [0] * V  # 0: unvisited, 1: visiting, 2: safe

    def is_safe(node: int) -> bool:
        if color[node] == 2:
            return True
        if color[node] == 1:
            return False
        color[node] = 1
        for neighbor in adj[node]:
            if not is_safe(neighbor):
                return False
        color[node] = 2
        return True

    safe_nodes = []
    for node in range(V):
        if is_safe(node):
            safe_nodes.append(node)

    return sorted(safe_nodes)
